def _apply_security() -> None:
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} FOR ALL TO app_runtime "
            "USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant())"
        )
    # Histories and stock movements are append-only for the application.
    for table in ("order_status_history", "inventory_transactions"):
        op.execute(f"REVOKE UPDATE, DELETE ON {table} FROM app_runtime")


def _invoice_immutability() -> None:
    """An issued invoice is a legal document: its money, parties and lines never change.

    Only status/cancellation fields, the payment cache (Phase 6), the PDF reference and the internal
    customer link (customer merges; the printed buyer is the frozen ``buyer_snapshot``) may move.
    """
    op.execute(
        """
        CREATE FUNCTION invoices_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF OLD.status <> 'DRAFT' AND (
               NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
            OR NEW.order_id IS DISTINCT FROM OLD.order_id
            OR NEW.issue_date IS DISTINCT FROM OLD.issue_date
            OR NEW.due_date IS DISTINCT FROM OLD.due_date
            OR NEW.currency IS DISTINCT FROM OLD.currency
            OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
            OR NEW.discount_total IS DISTINCT FROM OLD.discount_total
            OR NEW.tax_total IS DISTINCT FROM OLD.tax_total
            OR NEW.shipping_fee IS DISTINCT FROM OLD.shipping_fee
            OR NEW.grand_total IS DISTINCT FROM OLD.grand_total
            OR NEW.seller_snapshot IS DISTINCT FROM OLD.seller_snapshot
            OR NEW.buyer_snapshot IS DISTINCT FROM OLD.buyer_snapshot
            OR (OLD.status = 'CANCELLED' AND NEW.status <> 'CANCELLED')
          ) THEN
            RAISE EXCEPTION 'invoice % is % and cannot be changed', OLD.invoice_number, OLD.status
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NEW;
        END $$
        """
    )
    op.execute("CREATE TRIGGER invoices_locked BEFORE UPDATE ON invoices FOR EACH ROW EXECUTE FUNCTION invoices_guard()")
    op.execute(
        """
        CREATE FUNCTION invoice_items_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE parent_status text;
        BEGIN
          SELECT status INTO parent_status FROM invoices WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
          IF parent_status IS DISTINCT FROM 'DRAFT' THEN
            RAISE EXCEPTION 'lines of a % invoice cannot be changed', parent_status USING ERRCODE = 'check_violation';
          END IF;
          RETURN COALESCE(NEW, OLD);
        END $$
        """
    )
    op.execute(
        "CREATE TRIGGER invoice_items_locked BEFORE INSERT OR UPDATE OR DELETE ON invoice_items "
        "FOR EACH ROW EXECUTE FUNCTION invoice_items_guard()"
    )


def _default_tax_rates() -> None:
    """Existing businesses get VAT 13% (if VAT registered) or No VAT as their default rate."""
    op.execute(
        """
        INSERT INTO tax_rates (id, tenant_id, name, rate, is_default)
        SELECT gen_random_uuid(), t.id, 'VAT 13%', 13.00, t.vat_registered FROM tenants t
        UNION ALL
        SELECT gen_random_uuid(), t.id, 'No VAT', 0.00, NOT t.vat_registered FROM tenants t
        """
    )
